  if(c.name.equals(P+"NativeAreaMaterialAction$Context")){if(c.fields.stream().anyMatch(f->f.name.equals("nativeWeaponBreakTarget")))throw new AssertionError("duplicate single-target context");c.fields.add(new FieldNode(0,"nativeWeaponBreakTarget","I",null,null));c.fields.add(new FieldNode(0,"nativeWeaponBreakTargetId","J",null,null));c.fields.add(new FieldNode(0,"nativeWeaponBreakPeerReceipt","L"+P+"NativePlayerVitalCompletions$Receipt;",null,null));return;}
  if(c.name.equals(P+"NativeAreaMaterialAction")){var old=c.methods.stream().filter(m->m.name.equals("captureOutput")).findFirst().orElseThrow();old.name="nativeTargetOriginalCaptureOutput";var m=new MethodNode(ASM9,ACC_STATIC,"captureOutput",old.desc,null,null);for(int i=0;i<3;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESTATIC,P+"NativeWeaponBreakTargetLifecycle","captureOutput",old.desc,false));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);return;}
